from flask import Flask, jsonify, request, render_template,redirect,jsonifyimport  iplfrom database import Databasefrom collections import OrderedDictimport jsonimport secretsfrom functools import wrapsapp = Flask(__name__)app.json.sort_keys=False@app.route("/")def home():    return render_template("index.html")@app.route("/docs")def docs():    return render_template("docs.html")###code for genarating API key####--->>>>def load_keys():    try:        with open("api_keys.json", "r") as f:            return json.load(f)    except (FileNotFoundError, json.JSONDecodeError):        return {}def save_keys(data):    with open("api_keys.json","w") as f:        return json.dump(data, f,indent=4)@app.route("/generate-key",methods=["POST","GET"])def generate_key():    generated_key=None    error=None    if request.method=="POST":        email=request.form.get("email")        if not email:            error="please enter your email"        else:            new_key=f"key_{secrets.token_hex(16)}"            keys=load_keys()            keys[new_key]={"email":email,"active":True}            save_keys(keys)            generated_key=new_key    return render_template("api_key.html",api_key=generated_key,error=error)##### code for guarding api#####def require_api_key(func):    @wraps(func)    def wrapper(*args, **kwargs):        # 1. Request ke header se X-API-Key nikalo        provided_key = request.headers.get("X-API-Key")        # 2. api_keys.json se saari keys load karo        keys = load_keys()        # 3. Check karo key exist karti hai ya nahi aur active hai ya nahi        key_data = keys.get(provided_key)        if not provided_key or not key_data or not key_data.get("active"):            return jsonify({"error": "Invalid or missing API key"}), 401        # 4. Sab sahi hai to asal API function chala do        return func(*args, **kwargs)    return wrapper@app.route("/api/test-data", methods=["GET"])@require_api_keydef test_data():    return jsonify({        "status": "success",        "message": "API key verified! Yeh raha protected data."    })@app.route("/login")def login():    return render_template("login.html")@app.route("/register")def register():    return render_template("register.html")@app.route("/perform_registration",methods=["POST"])def perform_registration():    name=request.form.get("user_ka_name")    email=request.form.get("user_ka_email")    password=request.form.get("user_ka_passsword")    response=Database.insert(name,email,password)    if response:        return render_template("login.html",                               message="succesfully regsitered!!now you can login",                               success=True)    else:        return render_template("register.html",                               message="email already resgistered",                               success=False)@app.route("/perform_login",methods=["POST"])def perform_login():    email = (request.form.get('email') or '').strip()    password = request.form.get('password')    response=Database.check_login(email,password)    if response:        return redirect("/")    else:        return render_template(   "login.html",            message="incorrect email/passowrd",            success=False,       redirect_Home=False)@app.route("/api/teams")@require_api_keydef teams():    teams=ipl.teamsapi()    return jsonify(teams)@app.route("/api/players")@require_api_keydef players():    players=ipl.playersapi()    return jsonify(players)@app.route("/api/teamvteam")@require_api_keydef teamvteam():    team=request.args.get("team")    team2=request.args.get("team2")    response=ipl.teamVteamapi(team,team2)    print(response)    return jsonify(response)@app.route("/api/teamrecord")@require_api_keydef teamrecord():    team=request.args.get("team")    response=ipl.teamrecordapi(team)    return jsonify(response)@app.route("/api/teamagainstrecord")@require_api_keydef teamagainstrecord():    team=request.args.get("team")    response=ipl.teamagainstrecordapi(team)    return jsonify(response)@app.route("/api/batterrecord")@require_api_keydef batterrecord():    batter=request.args.get("batter")    response=ipl.batsmantrackapi(batter)    return jsonify(response)@app.route("/api/battervteamrecord")@require_api_keydef battervteamrecord():    batter=request.args.get("batter")    response=ipl.battervteamapi(batter)    return jsonify(response)@app.route("/api/bowler")@require_api_keydef bowlerstats():    bowler=request.args.get("bowler")    response=ipl.bowlerstats(bowler)    return jsonify(response)@app.route("/api/bowlervteamrecord")@require_api_keydef bowlervteamrecord():    bowler=request.args.get("bowler")    response=ipl.bowlerVteamapi(bowler)    return jsonify(response)@app.route("/api/battervbatter")@require_api_keydef battervbatterrecord():    batter1=request.args.get("batter1")    batter2=request.args.get("batter2")    response=ipl.battervbatter(batter1,batter2)    return jsonify(response)@app.route("/api/bowlervbowler")@require_api_keydef bowlervbowler():    bowler1=request.args.get("bowler1")    bowler2=request.args.get("bowler2")    response=ipl.bowlervbowler(bowler1,bowler2)    return jsonify(response)@app.route("/api/orangecapholder")@require_api_keydef orangecapholder():    response=ipl.orangecapapi()    return jsonify(response)@app.route("/api/purplecapholder")@require_api_keydef purplecapholder():    response=ipl.purplecapapi()    return jsonify(response)app.run(host='0.0.0.0', port=8080,debug=True)